ALTER TABLE public.orders ADD COLUMN started boolean NOT NULL DEFAULT false,ADD COLUMN supplier_id uuid REFERENCES public.suppliers(id),ADD COLUMN price numeric NOT NULL DEFAULT 0 CHECK(price>=0);
CREATE TABLE public.production_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),order_id uuid NOT NULL REFERENCES public.orders(id),product_id uuid NOT NULL REFERENCES public.products(id),quantity numeric NOT NULL CHECK(quantity>0),UNIQUE(order_id,product_id)); GRANT SELECT ON public.production_reservations TO authenticated; GRANT ALL ON public.production_reservations TO service_role; ALTER TABLE public.production_reservations ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.production_reservations FOR SELECT TO authenticated USING(company_id=public.current_company() AND public.erp_allowed('production','read'));
CREATE OR REPLACE FUNCTION public.move_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.company_id IS DISTINCT FROM public.current_company() OR NEW.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Responsável ou empresa inválida'; END IF; IF NEW.type NOT IN ('Entrada de compras','Saída para produção','Entrada de produtos fabricados','Perdas e desperdícios','Ajustes de inventário','Devoluções','Venda') THEN RAISE EXCEPTION 'Tipo inválido'; END IF; IF NEW.type IN ('Entrada de compras','Entrada de produtos fabricados') AND NEW.quantity<0 OR NEW.type IN ('Saída para produção','Perdas e desperdícios','Venda') AND NEW.quantity>0 THEN RAISE EXCEPTION 'Sinal inválido'; END IF; UPDATE public.products SET stock=stock+NEW.quantity WHERE id=NEW.product_id AND company_id=NEW.company_id AND stock+NEW.quantity>=reserved; IF NOT FOUND THEN RAISE EXCEPTION 'Saldo insuficiente ou reservado'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.production_action(order_id uuid,action text,responsible text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders;b record;p public.products; BEGIN IF NOT public.erp_allowed('production','update') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO o FROM public.orders WHERE id=order_id AND company_id=public.current_company() FOR UPDATE; IF NOT FOUND OR o.status<>'Aberta' OR o.type<>'Produção' THEN RAISE EXCEPTION 'Ordem indisponível'; END IF; PERFORM id FROM public.products WHERE company_id=o.company_id ORDER BY id FOR UPDATE; SELECT * INTO p FROM public.products WHERE id=o.product_id; IF action='Iniciar' THEN IF o.started THEN RAISE EXCEPTION 'Produção já iniciada'; END IF; IF NOT EXISTS(SELECT 1 FROM public.bom WHERE product_id=p.id) THEN RAISE EXCEPTION 'Cadastre a ficha técnica'; END IF; FOR b IN SELECT * FROM public.bom WHERE product_id=p.id LOOP UPDATE public.products SET reserved=reserved+b.quantity*o.quantity/p.batch WHERE id=b.component_id AND stock-reserved>=b.quantity*o.quantity/p.batch; IF NOT FOUND THEN RAISE EXCEPTION 'Estoque insuficiente para reservar'; END IF; INSERT INTO public.production_reservations(company_id,order_id,product_id,quantity) VALUES(o.company_id,o.id,b.component_id,b.quantity*o.quantity/p.batch); END LOOP; UPDATE public.orders SET started=true WHERE id=o.id; ELSIF action IN ('Concluir','Cancelar') THEN IF action='Concluir' AND NOT o.started THEN RAISE EXCEPTION 'Inicie a produção antes'; END IF; FOR b IN SELECT * FROM public.production_reservations WHERE production_reservations.order_id=o.id LOOP UPDATE public.products SET reserved=reserved-b.quantity WHERE id=b.product_id; IF action='Concluir' THEN INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(b.product_id,-b.quantity,'Saída para produção',responsible); END IF; END LOOP; DELETE FROM public.production_reservations WHERE production_reservations.order_id=o.id; IF action='Concluir' THEN INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(o.product_id,o.quantity,'Entrada de produtos fabricados',responsible); END IF; UPDATE public.orders SET status=CASE WHEN action='Concluir' THEN 'Concluída' ELSE 'Cancelada' END,started=false WHERE id=o.id; ELSE RAISE EXCEPTION 'Ação inválida'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.finish_order(order_id uuid,responsible text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders;p public.products; BEGIN SELECT * INTO o FROM public.orders WHERE id=order_id AND company_id=public.current_company() FOR UPDATE; IF NOT FOUND OR o.status<>'Aberta' THEN RAISE EXCEPTION 'Ordem indisponível'; END IF; IF o.type='Produção' THEN PERFORM public.production_action(o.id,'Concluir',responsible); RETURN; END IF; IF NOT public.erp_allowed('purchases','update') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO p FROM public.products WHERE id=o.product_id; INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(o.product_id,o.quantity,'Entrada de compras',responsible); IF o.quantity*COALESCE(NULLIF(o.price,0),p.cost)>0 THEN INSERT INTO public.finance(type,description,amount,due_date,supplier_id,source_id) VALUES('Pagar','Compra de '||p.name,o.quantity*COALESCE(NULLIF(o.price,0),p.cost),o.due_date,COALESCE(o.supplier_id,p.supplier_id),o.id); END IF; UPDATE public.orders SET status='Concluída' WHERE id=o.id; END $$;
CREATE FUNCTION public.purchase_action(request_id uuid,action text,received numeric DEFAULT 0,invoice_number text DEFAULT '',responsible text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.purchase_requests;p public.products; BEGIN SELECT * INTO r FROM public.purchase_requests WHERE id=request_id AND company_id=public.current_company() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pedido indisponível'; END IF; IF action='Aprovar' THEN IF NOT public.erp_allowed('purchases','approve') OR r.status NOT IN ('Solicitada','Cotação') THEN RAISE EXCEPTION 'Sem permissão ou status inválido'; END IF; UPDATE public.purchase_requests SET status='Aprovada' WHERE id=r.id; INSERT INTO public.orders(id,product_id,type,quantity,due_date,supplier_id,price) VALUES(r.id,r.product_id,'Compra',r.quantity,r.due_date,r.supplier_id,r.price); ELSIF action='Receber' THEN IF NOT public.erp_allowed('purchases','update') OR r.status<>'Aprovada' OR received<>r.quantity THEN RAISE EXCEPTION 'Confira a quantidade total do pedido aprovado'; END IF; SELECT * INTO p FROM public.products WHERE id=r.product_id; INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(r.product_id,received,'Entrada de compras',responsible); IF received*r.price>0 THEN INSERT INTO public.finance(type,description,amount,due_date,supplier_id,source_id) VALUES('Pagar','Compra de '||p.name,received*r.price,r.due_date,r.supplier_id,r.id); END IF; UPDATE public.purchase_requests SET status='Recebida',received_quantity=received,invoice=invoice_number WHERE id=r.id; UPDATE public.orders SET status='Concluída' WHERE id=r.id; ELSE RAISE EXCEPTION 'Ação inválida'; END IF; END $$;
CREATE FUNCTION public.record_sale(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s uuid;item jsonb;p public.products;q numeric;price numeric;total numeric:=0;discount numeric;customer uuid;credit boolean;kind text; BEGIN IF NOT public.erp_allowed('sales','create') THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF jsonb_array_length(payload->'items')=0 THEN RAISE EXCEPTION 'Adicione produtos'; END IF; customer=NULLIF(payload->>'customer_id','')::uuid;credit=COALESCE((payload->>'credit')::boolean,false);kind=COALESCE(payload->>'kind','Venda');discount=COALESCE((payload->>'discount')::numeric,0); IF customer IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.customers WHERE id=customer AND company_id=public.current_company()) THEN RAISE EXCEPTION 'Cliente inválido'; END IF; PERFORM id FROM public.products WHERE company_id=public.current_company() ORDER BY id FOR UPDATE; INSERT INTO public.sales(customer_id,kind,payment_method,credit,due_date,discount) VALUES(customer,kind,COALESCE(payload->>'payment_method','Dinheiro'),credit,COALESCE(NULLIF(payload->>'due_date','')::date,current_date),discount) RETURNING id INTO s; FOR item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP SELECT * INTO p FROM public.products WHERE id=(item->>'product_id')::uuid AND company_id=public.current_company() AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Produto inválido'; END IF; q=(item->>'quantity')::numeric;price=(item->>'price')::numeric; IF q<=0 OR price<0 THEN RAISE EXCEPTION 'Quantidade ou preço inválido'; END IF; INSERT INTO public.sale_items(sale_id,product_id,quantity,price,cost) VALUES(s,p.id,q,price,p.cost);total=total+q*price; IF kind='Venda' THEN INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(p.id,-q,'Venda',COALESCE(NULLIF(payload->>'responsible',''),'Operador de vendas')); END IF; END LOOP; total=total-discount; IF total<=0 OR discount<0 THEN RAISE EXCEPTION 'Total deve ser positivo'; END IF; IF credit THEN IF customer IS NULL OR total+(SELECT COALESCE(sum(amount),0) FROM public.finance WHERE customer_id=customer AND status='Pendente' AND type='Receber')>(SELECT credit_limit FROM public.customers WHERE id=customer) THEN RAISE EXCEPTION 'Limite de crédito insuficiente'; END IF; END IF; UPDATE public.sales SET total=total,status=CASE WHEN kind='Venda' THEN 'Confirmada' ELSE 'Rascunho' END WHERE id=s; IF kind='Venda' THEN INSERT INTO public.finance(type,description,amount,due_date,paid_at,customer_id,payment_method,status,source_id) VALUES('Receber','Venda '||s::text,total,COALESCE(NULLIF(payload->>'due_date','')::date,current_date),CASE WHEN credit THEN NULL ELSE current_date END,customer,COALESCE(payload->>'payment_method','Dinheiro'),CASE WHEN credit THEN 'Pendente' ELSE 'Pago' END,s); END IF; RETURN s; END $$;
CREATE FUNCTION public.cancel_sale(sale_id uuid,responsible text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sales;i record; BEGIN IF NOT public.erp_allowed('sales','update') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO s FROM public.sales WHERE id=sale_id AND company_id=public.current_company() FOR UPDATE; IF NOT FOUND OR s.status='Cancelada' THEN RAISE EXCEPTION 'Venda indisponível'; END IF; IF s.status='Confirmada' THEN FOR i IN SELECT * FROM public.sale_items WHERE sale_items.sale_id=s.id ORDER BY product_id LOOP INSERT INTO public.movements(product_id,quantity,type,responsible) VALUES(i.product_id,i.quantity,'Devoluções',responsible); END LOOP; UPDATE public.finance SET status='Cancelado' WHERE source_id=s.id; END IF; UPDATE public.sales SET status='Cancelada' WHERE id=s.id; END $$;
CREATE FUNCTION public.protect_posted() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND (TG_TABLE_NAME='sales' OR TG_TABLE_NAME='sale_items' AND EXISTS(SELECT 1 FROM public.sales WHERE id=COALESCE(NEW.sale_id,OLD.sale_id) AND status<>'Rascunho') OR TG_TABLE_NAME='orders' AND (OLD.started OR OLD.status<>'Aberta') OR TG_TABLE_NAME='purchase_requests' AND OLD.status IN ('Aprovada','Recebida') OR TG_TABLE_NAME='finance' AND OLD.source_id IS NOT NULL) THEN RAISE EXCEPTION 'Use a operação integrada para alterar este registro'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER protect_sales BEFORE UPDATE OR DELETE ON public.sales FOR EACH ROW EXECUTE FUNCTION public.protect_posted(); CREATE TRIGGER protect_items BEFORE UPDATE OR DELETE ON public.sale_items FOR EACH ROW EXECUTE FUNCTION public.protect_posted(); CREATE TRIGGER protect_orders BEFORE UPDATE OR DELETE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.protect_posted(); CREATE TRIGGER protect_purchases BEFORE UPDATE OR DELETE ON public.purchase_requests FOR EACH ROW EXECUTE FUNCTION public.protect_posted(); CREATE TRIGGER protect_finance BEFORE UPDATE OR DELETE ON public.finance FOR EACH ROW EXECUTE FUNCTION public.protect_posted();
REVOKE ALL ON FUNCTION public.production_action(uuid,text,text),public.purchase_action(uuid,text,numeric,text,text),public.record_sale(jsonb),public.cancel_sale(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.production_action(uuid,text,text),public.purchase_action(uuid,text,numeric,text,text),public.record_sale(jsonb),public.cancel_sale(uuid,text) TO authenticated;
CREATE FUNCTION public.settle_finance(record_id uuid,bank uuid DEFAULT NULL,method text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.finance; BEGIN IF NOT public.erp_allowed('finance','update') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO f FROM public.finance WHERE id=record_id AND company_id=public.current_company() AND status='Pendente' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Conta indisponível'; END IF; UPDATE public.finance SET status='Pago',paid_at=current_date,bank_id=bank,payment_method=method WHERE id=f.id; END $$;
REVOKE ALL ON FUNCTION public.settle_finance(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.settle_finance(uuid,uuid,text) TO authenticated;